// === Tab: mySketch ===
// Continuous 🥨 #WCCChallenge 
//
// Ola Raph and fellow creative coders
// inspired by the iconic album cover from joy divisions "unknown pleasures"
// https://en.wikipedia.org/wiki/Unknown_Pleasures#Artwork_and_packaging
// created a continuous 3D environment with retro color

function setup() {
  pixelDensity(1);
  createCanvas(windowWidth, windowHeight, WEBGL);
  frameRate(30);
}

function draw() {
  background(0, 0, 8);

  rotateX(0.85);
  // rotateX(frameCount * 0.01);
  // rotateY(frameCount * 0.01);
  // fill(48, 8, 40);

  const sizeBar = 25;
  const numBarsX = 60;
  const numBarsY = 60;
  let noiseOffX = 111 + frameCount;
  let noiseOffY = 333 + frameCount * 2;

  stroke(0); // 32, 192, 160)
  // fill(32, 192, 160, 32);
  let posY = (-numBarsY / 2) * sizeBar;
  for (let y = 0; y < numBarsY; y+=2) {
    fill(32, 192, 160, map(y, 0, numBarsY, 4, 64));
    let posX = (-numBarsX / 2) * sizeBar;
    for (let x = 0; x < numBarsX; x++) {
			// get height (n) as noise
      const n = noise((x + noiseOffX) * 0.15, (y - noiseOffY) * 0.215);
			// scale n * 256 and shrink on edges (with limit 0.1)
      const d =
        n *
        256 *
        max(0.1, easeInOutExpo(1 - abs(x - numBarsX / 2) / (numBarsX / 2)));
      rect3d(posX, posY, sizeBar, sizeBar, d);
      posX += sizeBar;
    }
    posY += 2*sizeBar;
  }

  // // noLoop() removed for animation
}

// https://easings.net/#easeInOutSine
function easeInOutExpo(x) {
  return x === 0
    ? 0
    : x === 1
    ? 1
    : x < 0.5
    ? Math.pow(2, 20 * x - 10) / 2
    : (2 - Math.pow(2, -20 * x + 10)) / 2;
}
function easeInOutSine(x) {
  return -(Math.cos(Math.PI * x) - 1) / 2;
}

function rect3d(x, y, w, h, d) {
  push();
  translate(x, y, d / 2);
  box(w, h, d);
  pop();
}
